class BankAccount {
  // Private field (JS mein # lagate hain)
  #balance;

  constructor(initialDeposit) {
    this.#balance = initialDeposit;
  }

  // Public method - yaha se balance check hoga
  getBalance() {
    return this.#balance;
  }

  // Public method - validation ke baad hi balance badhega
  deposit(amount) {
    if (amount > 0) {
      this.#balance += amount;
    } else {
      throw new Error("Paisa negative nahi ho sakta!");
    }
  }
}

