// ❌ BAD: OrderService direct MySQLDatabase pe depend kar rahi hai
class MySQLDatabase { save(order) { /* save logic */ } }

class OrderService {
  constructor() {
    this.db = new MySQLDatabase(); // Tight coupling!
  }
  process(order) { this.db.save(order); }
}

// ✅ GOOD: OrderService ko koi bhi Database object pass (inject) kiya jaa sakta hai
class OrderService {
  constructor(database) {
    this.db = database; // Dependency Injection (DIP achieved)
  }
  process(order) { this.db.save(order); }
}

const mysqlDb = new MySQLDatabase();
const orderService = new OrderService(mysqlDb);

