// Products
class Truck { deliver() { console.log("Delivering by land 🚛"); } }
class Ship { deliver() { console.log("Delivering by sea 🚢"); } }

// Creator Base
class Logistics {
  // Factory Method
  createTransport() { throw new Error("Subclass must implement"); }

  // Core business logic (ye badlega nahi)
  planDelivery() {
    const transport = this.createTransport();
    transport.deliver();
  }
}

// Concrete Creators
class RoadLogistics extends Logistics {
  createTransport() { return new Truck(); }
}
class SeaLogistics extends Logistics {
  createTransport() { return new Ship(); }
}

const myDelivery = new RoadLogistics();
myDelivery.planDelivery(); // Delivering by land 🚛

// The Abstract Factory Interface
class GUIFactory {
  createButton() {}
  createCheckbox() {}
}

class MacFactory extends GUIFactory {
  createButton() { return new MacButton(); }
  createCheckbox() { return new MacCheckbox(); }
}

class WinFactory extends GUIFactory {
  createButton() { return new WinButton(); }
  createCheckbox() { return new WinCheckbox(); }
}

// Client ko nahi farq padta ki OS kya hai
function renderApp(factory) {
  const button = factory.createButton();
  const checkbox = factory.createCheckbox();
  button.paint();
  checkbox.paint();
}

// OS ke hisaab se factory inject kardo
const os = 'mac';
renderApp(os === 'mac' ? new MacFactory() : new WinFactory());

class Burger {
  constructor(builder) {
    this.bread = builder.bread;
    this.patty = builder.patty;
    this.cheese = builder.cheese || false;
    this.tomato = builder.tomato || false;
  }
}

class BurgerBuilder {
  constructor(bread, patty) {
    // Required properties
    this.bread = bread;
    this.patty = patty;
  }

  // Optional steps (return 'this' for method chaining)
  addCheese() {
    this.cheese = true;
    return this; 
  }

  addTomato() {
    this.tomato = true;
    return this;
  }

  build() {
    return new Burger(this);
  }
}

// Method Chaining magic!
const myBurger = new BurgerBuilder('Whole Wheat', 'Veggie')
  .addCheese()
  .addTomato()
  .build();

// Old system (Jisko humein connect karna hai)
class LegacyPaymentGateway {
  processPaymentInDollars(amountInDollars) {
    console.log(`Processed $${amountInDollars}`);
  }
}

// Target interface (Naya system jisko rupees chahiye)
class ModernPaymentInterface {
  pay(amountInRupees) { throw new Error("Implement me"); }
}

// ADAPTER: Naye system ko purane se connect kar raha hai
class PaymentAdapter extends ModernPaymentInterface {
  constructor(legacyGateway) {
    super();
    this.legacy = legacyGateway;
  }

  // Naya system .pay() call karega
  pay(amountInRupees) {
    // Adapter ne convert kiya (Interface transformation)
    const dollars = amountInRupees / 83; 
    // Purane system ko uski bhasha mein de diya
    this.legacy.processPaymentInDollars(dollars);
  }
}

const legacy = new LegacyPaymentGateway();
const adapter = new PaymentAdapter(legacy);

// Client ko farq nahi padta, usne apni local bhasha (rupees) mein baat ki
adapter.pay(8300); // Processed $100

// Base Component
class Coffee {
  getCost() { return 100; }
  getDescription() { return "Basic Coffee"; }
}

// Base Decorator
class CoffeeDecorator {
  constructor(coffee) { this.coffee = coffee; }
  getCost() { return this.coffee.getCost(); }
  getDescription() { return this.coffee.getDescription(); }
}

// Concrete Decorators
class MilkDecorator extends CoffeeDecorator {
  getCost() { return this.coffee.getCost() + 20; }
  getDescription() { return this.coffee.getDescription() + ", Milk"; }
}

class SugarDecorator extends CoffeeDecorator {
  getCost() { return this.coffee.getCost() + 10; }
  getDescription() { return this.coffee.getDescription() + ", Sugar"; }
}

// Wrapping process
let myCoffee = new Coffee(); // 100
myCoffee = new MilkDecorator(myCoffee); // 100 + 20
myCoffee = new SugarDecorator(myCoffee); // 120 + 10

console.log(myCoffee.getDescription()); // Basic Coffee, Milk, Sugar
console.log(myCoffee.getCost()); // 130

// Complex subsystem parts
class Inventory { checkStock() { return true; } }
class Payment { deductAmount() { return true; } }
class Shipping { arrangeDelivery() { console.log("Delivering..."); } }

// The Facade (Hiding all the complexity)
class OrderFacade {
  constructor() {
    this.inventory = new Inventory();
    this.payment = new Payment();
    this.shipping = new Shipping();
  }

  // Simplified method for the client
  placeOrder() {
    if (this.inventory.checkStock()) {
      if (this.payment.deductAmount()) {
        this.shipping.arrangeDelivery();
        console.log("Order placed successfully!");
      }
    }
  }
}

// Client bas 1 line mein order place kar raha hai
const order = new OrderFacade();
order.placeOrder();

class RealSubject {
  request() {
    console.log("RealSubject: Handling request. (Heavy Operation)");
  }
}

class ProxySubject {
  constructor(realSubject) {
    this.realSubject = realSubject;
  }

  // Access control and logic before forwarding
  request() {
    if (this.checkAccess()) {
      this.realSubject.request();
      this.logAccess();
    } else {
      console.log("Proxy: Access Denied!");
    }
  }

  checkAccess() {
    console.log("Proxy: Checking access permissions...");
    return true; 
  }
  logAccess() {
    console.log("Proxy: Logging time of request.");
  }
}

const real = new RealSubject();
const proxy = new ProxySubject(real);

proxy.request(); 
// Checking access... 
// Handling request... 
// Logging time...
